export default {

	selectedRequest: [],
	defaultAvatarBase64: "data:image/jpeg;base64,",

	async bonitaOnPageLoad () {
		//Modify API GET Queries to adapt for your case
		await getStrategyList.run();
		await getUserTasks.run();
		this.countBuckets();
	},	

	async refreshData() {
		getStrategyList.run();
		getUserTasks.run();
		this.bonitaOnPageLoad();
	},

	getLocalDateToday () {
		const localDate = new Date().toISOString();
		return localDate
	},

	forgeDocumentImageURL (documentContext){
		const forgedURL = appsmith.URL.protocol + "//" + appsmith.URL.hostname + "/bonita/API/formsDocumentImage?fileName="+ encodeURIComponent(documentContext.fileName) + "&document=" + encodeURIComponent(documentContext.id);
		return forgedURL;
	},

	forgeDownloadDocumentURL (documentURL){
		const forgedURL = appsmith.URL.protocol + "//" + appsmith.URL.hostname + "/bonita/API/" + documentURL;
		return forgedURL;
	},

	forgeAvatarURL (avatarURL){
		let avatar = ""
		if (avatarURL == "icons/default/icon_user.png" || avatarURL == null){
			avatar = this.defaultAvatarBase64;
		}else{
			const avatarURLFormatted = avatarURL.replace(/[.]/g, '');
			avatar = appsmith.URL.protocol + "//" + appsmith.URL.hostname + "/bonita" + avatarURLFormatted;
			//const forgedUrl = "http://localhost/bonita/API/avatars/1"
		}
		return avatar
	},

	showTaskModal(caseId){
		return getUserTasks.data.some(item => item.parentCaseId == caseId);
	},

	setSelectedRequestTask (request) {
		this.selectedRequest = request;
		let taskData = this.renameAttribute(getUserTasks.data, "name", "taskName");
		taskData = this.renameAttribute(taskData,"id","taskId");
		const task = taskData.find(item => item.rootCaseId == request.requestId);
		this.selectedRequest.taskData = task;
		return this.selectedRequest;
	},

	setSelectedRequest(request){
		this.selectedRequest = request;
		return this.selectedRequest;
	},//CaseIDKey is the attribute used in the bdm object to store the processInstanceId

	combineTasksBDM(taskData,bdmData,caseIdKey) {
		return taskData.map(row=> {
			var taskOrder = bdmData.find(order => order[caseIdKey] == row.caseId)
			return taskOrder ? { ...row, ...taskOrder } : null;
		}).filter(row => row !== null); // Filter out rows where taskOrder was not found
	},

	renameAttribute(array, oldKey, newKey) {
		return array.map(item => {
			if (item.hasOwnProperty(oldKey)) {
				item[newKey] = item[oldKey];
				delete item[oldKey];
			}
			return item;
		});
	},
	countBuckets() {
		// Initialize counters for each status
		let counters = {
			bucket1: 0,
			bucket2: 0,
			bucket3: 0
		};
		getStrategyList.data.forEach(item => {
			// Check the "statut" and increment the corresponding counter
			if (item.bucketId === 1) {
				counters.bucket1++;
			} else if (item.bucketId === 2) {
				counters.bucket2++;
			} else if (item.bucketId === 3) {
				counters.bucket3++
			}	
			return counters;
		});

		// Return the count object
		return counters;
	},
}

